import{_ as r,o as t,c as i,a2 as n}from"./chunks/framework.Uc5-6EiL.js";const p=JSON.parse('{"title":"Programmieren mit KI","description":"","frontmatter":{},"headers":[],"relativePath":"uebungen/1-programmieren-mit-ki.md","filePath":"content/Übungen/1 - Programmieren mit KI.md","lastUpdated":null}'),a={name:"uebungen/1-programmieren-mit-ki.md"};function s(o,e,l,m,u,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="programmieren-mit-ki" tabindex="-1">Programmieren mit KI <a class="header-anchor" href="#programmieren-mit-ki" aria-label="Permalink to &quot;Programmieren mit KI&quot;">​</a></h1><p>KI wird gerade zum Standard in der Progrmmierung. Nachdem wir nun die Grundlagen angeschaut haben, versuchen wir als letzten Auftrag das Programmieren mit KI zu üben und zu schauen, wie weit wir kommen.</p><p><strong>Das Ziel</strong> Das Ziel ist relativ einfach: Wir entscheiden uns für ein Website projekt (Portfolio, Game, Website) und versuchen, das mithilfe von KI möglichst gut umzusetzen.</p><p><strong>Der Auftrag</strong></p><ol><li>Wählt selber ein Ziel aus. Kann auch etwas sein, woran ihr bereits arbeitet. Schreibe eine Kurze Beschreibung auf unsere gemeinsme Pinwand: <a href="https://canva.link/6bzh3ksbodvos58" target="_blank" rel="noreferrer">https://canva.link/6bzh3ksbodvos58</a></li><li>Versuche, möglichst weit zu kommen</li><li>Präsentiert das Ergebnis (kurz)</li></ol><p><strong>Methoden</strong></p><p>Wir können folgende Methoden anwenden:</p><p><em>Chatbot + VS Code</em> Lasst euch von einem Chatbot (ChatGPT, Gemini, Claude, Le Chat) den Code als eine HTML-Datei mit CSS und JavaScript erstellen. Kopiert ihn in VS Code in eine index.html und öffnet sie mit «Live Server». So seht ihr reines JavaScript, wie im Unterricht gelernt.</p><p><em>Claude Artifacts</em> Auf claude.ai beschreibt ihr euer Projekt, und Claude zeigt es direkt im Chat als Vorschau an («Artifact»). Mit «Publish» erhaltet ihr einen Link zum Teilen. Gratis, aber die Anzahl Nachrichten ist begrenzt. Wichtig: In den Einstellungen unter «Capabilities» muss «Code execution and file creation» aktiviert sein.</p><p><em>Google AI Studio</em> Auf aistudio.google.com beschreibt ihr unter «Build», was ihr wollt, und die KI baut eine ganze Web-App mit Vorschau. Gratis, aber ihr braucht ein Google-Konto. Der Code ist in React geschrieben.</p><p><em>App-Builder</em> Lovable, Bolt.new oder Replit bauen aus einer Beschreibung eine App direkt im Browser. Achtung: Die Gratis-Version ist stark begrenzt, und ihr braucht ein eigenes Konto.</p><ul><li><a href="https://lovable.dev" target="_blank" rel="noreferrer">https://lovable.dev</a></li><li><a href="https://Bolt.new" target="_blank" rel="noreferrer">https://Bolt.new</a></li><li><a href="https://replit.com" target="_blank" rel="noreferrer">https://replit.com</a></li></ul><p><strong>Links</strong> Inspiration gute Websiten: <a href="https://www.awwwards.com" target="_blank" rel="noreferrer">https://www.awwwards.com</a></p>',13)])])}const c=r(a,[["render",s]]);export{p as __pageData,c as default};
